<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class PurchaseInvoice extends Model { protected $fillable=['business_id','branch_id','supplier_id','purchase_order_id','user_id','invoice_number','supplier_invoice_number','invoice_date','subtotal','discount','vat','grand_total','paid_amount','payment_status','status','received_at','notes']; protected function casts():array{return ['invoice_date'=>'date','received_at'=>'datetime','subtotal'=>'decimal:2','discount'=>'decimal:2','vat'=>'decimal:2','grand_total'=>'decimal:2','paid_amount'=>'decimal:2'];} public function supplier(){return $this->belongsTo(Supplier::class);} public function branch(){return $this->belongsTo(Branch::class);} public function order(){return $this->belongsTo(PurchaseOrder::class,'purchase_order_id');} public function items(){return $this->hasMany(PurchaseInvoiceItem::class);} }
